    band_count = (h + 1) // 5
    tile_count = (w + 1) // 5
    colors = [grid[1 + 5*r][1] for r in range(band_count)]
    marker_colors = set(colors)
    motif = None
    for br in range(band_count):
        for bc in range(tile_count):
            cells = {(dr, dc) for dr in range(4) for dc in range(4)
                     if grid[br*5 + dr][bc*5 + dc] in range(1, 10)
                     and grid[br*5 + dr][bc*5 + dc] not in marker_colors}
            if cells:
                motif = cells
                break
        if motif:
            break
    for br, color in enumerate(colors):
        for bc in range(tile_count):
            for dr, dc in motif:
                out[br*5 + dr][bc*5 + dc] = color
    return out

