def transform(grid):
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v != bg]
        for a, b in zip(cols, cols[1:]):
            if grid[r][a] == grid[r][b]:
                for c in range(a + 1, b):
                    if grid[r][c] == bg: out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != bg]
        for a, b in zip(rows, rows[1:]):
            if grid[a][c] == grid[b][c]:
                for r in range(a + 1, b):
                    if grid[r][c] == bg: out[r][c] = 2
    return out

def transform(grid):
    n = len(grid[0])
    mid = n // 2
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= mid:
            out[r][mid - r] = 2
            out[r][mid + r] = 2
        if r >= 3:
            seed = mid - 1
            radius = r - 3
            for c in range(max(0, seed - radius), min(n - 1, seed + radius) + 1):
                if (c - seed - radius) % 4 == 0 and out[r][c] == 0:
                    out[r][c] = 1
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find solid rectangular outlines and fill their interiors with 8,
    # leaving existing colored cells unchanged.
    for r0 in range(h):
        for c0 in range(w):
            if grid[r0][c0] != 2:
                continue
            for r1 in range(r0 + 2, h):
                for c1 in range(c0 + 2, w):
                    if (all(grid[r0][c] == 2 and grid[r1][c] == 2 for c in range(c0, c1 + 1))
                        and all(grid[r][c0] == 2 and grid[r][c1] == 2 for r in range(r0, r1 + 1))):
                        for r in range(r0 + 1, r1):
                            for c in range(c0 + 1, c1):
                                if grid[r][c] == 0:
                                    out[r][c] = 8
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    fill_by_side = {5: 8, 7: 4, 9: 3}
    for r0 in range(h):
        for c0 in range(w):
            if grid[r0][c0] != 2:
                continue
            for r1 in range(r0 + 2, h):
                for c1 in range(c0 + 2, w):
                    side = r1 - r0 + 1
                    if side != c1 - c0 + 1 or side not in fill_by_side:
                        continue
                    if (all(grid[r0][c] == 2 and grid[r1][c] == 2 for c in range(c0, c1 + 1))
                        and all(grid[r][c0] == 2 and grid[r][c1] == 2 for r in range(r0, r1 + 1))):
                        fill = fill_by_side[side]
                        for r in range(r0 + 1, r1):
                            for c in range(c0 + 1, c1):
                                if grid[r][c] == 0:
                                    out[r][c] = fill
    return out

