from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 1 and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 1 and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1 and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return [[4 if grid[r][c] == 1 and (r,c) not in seen else grid[r][c] for c in range(w)] for r in range(h)]

from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set(); q = deque()
    for r in range(h):
        for c in (0, w-1):
            if grid[r][c] == bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0, h-1):
            if grid[r][c] == bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return [[4 if grid[r][c]==bg and (r,c) not in seen else grid[r][c] for c in range(w)] for r in range(h)]

def transform(grid):
    colors = sorted({v for row in grid for v in row if v != 0})
    tiles = {}
    for c in colors:
        pts = [(r, k) for r, row in enumerate(grid) for k, v in enumerate(row) if v == c]
        r0, r1 = min(r for r, k in pts), max(r for r, k in pts)
        c0, c1 = min(k for r, k in pts), max(k for r, k in pts)
        tiles[c] = [[c if grid[r][k] == c else 0 for k in range(c0, c1+1)] for r in range(r0, r1+1)]
    return [[v for c in colors for v in tiles[c][r]] for r in range(3)]
